+func TestDurabilityDisableWAL(t *testing.T) {
+	defer leaktest.AfterTest(t)()
+
+	var called atomic.Bool
+	d, err := Open("", &Options{
+		FS:         vfs.NewMem(),
+		DisableWAL: true,
+		EventListener: &EventListener{
+			BatchDurable: func(info BatchDurableInfo) {
+				called.Store(true)
+			},
+		},
+	})
+	require.NoError(t, err)
+	defer func() {
+		require.NoError(t, d.Close())
+	}()
+
+	require.NoError(t, d.Set([]byte("k"), []byte("v"), NoSync))
+	require.False(t, called.Load())
+
+	// Wait APIs and DurabilityNotify must return nil immediately when DisableWAL is true.
+	require.NoError(t, d.WaitForDurability(0))
+	require.NoError(t, d.WaitForDurability(9999))
+	require.NoError(t, d.WaitForDurabilityBatch([]base.SeqNum{100, 200}))
+	require.NoError(t, d.WaitForJobDurability(0))
+	require.NoError(t, d.WaitForJobDurability(999))
+
+	ch := d.DurabilityNotify(9999)
+	select {
+	case notifyErr := <-ch:
+		require.NoError(t, notifyErr)
+	default:
+		t.Fatal("expected DurabilityNotify to return pre-filled nil channel when DisableWAL is true")
+	}
+}
+
+func TestDurabilityContextCancellation(t *testing.T) {
+	defer leaktest.AfterTest(t)()
+
+	d, err := Open("", &Options{FS: vfs.NewMem()})
+	require.NoError(t, err)
+	defer func() {
+		require.NoError(t, d.Close())
+	}()
+
+	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Millisecond)
+	defer cancel()
+
+	err = d.WaitForDurabilityContext(ctx, 500)
+	require.ErrorIs(t, err, context.DeadlineExceeded)
+	require.Equal(t, int64(0), d.DurabilityStats().PendingWaiters)
+
+	ctx2, cancel2 := context.WithCancel(context.Background())
+	cancel2()
+	err = d.WaitForDurabilityBatchContext(ctx2, []base.SeqNum{500})
+	require.ErrorIs(t, err, context.Canceled)
+	require.Equal(t, int64(0), d.DurabilityStats().PendingWaiters)
+}
+
+func TestDurabilityErrorFsInjection(t *testing.T) {
+	defer leaktest.AfterTest(t)()
+
+	var events []BatchDurableInfo
+	var mu sync.Mutex
+
+	injectSync := atomic.Bool{}
+	inj := errorfs.InjectorFunc(func(op errorfs.Op) error {
+		if (op.Kind == errorfs.OpFileSync || op.Kind == errorfs.OpFileSyncData) &&
+			strings.HasSuffix(op.Path, ".log") && injectSync.Load() {
+			return errorfs.ErrInjected
+		}
+		return nil
+	})
+	fs := errorfs.Wrap(vfs.NewMem(), inj)
+
+	d, err := Open("", &Options{
+		FS:     fs,
+		Logger: base.NoopLoggerAndTracer{},
+		EventListener: &EventListener{
+			BatchDurable: func(info BatchDurableInfo) {
+				mu.Lock()
+				events = append(events, info)
+				mu.Unlock()
+			},
+		},
+	})
+	require.NoError(t, err)
+	defer func() {
+		_ = d.Close()
+	}()
+
+	require.NoError(t, d.Set([]byte("a"), []byte("1"), Sync))
+	injectSync.Store(true)
+	err = d.Set([]byte("b"), []byte("2"), Sync)
+	require.ErrorIs(t, err, errorfs.ErrInjected)
+
+	mu.Lock()
+	require.Len(t, events, 2)
+	require.NoError(t, events[0].Err)
+	require.ErrorIs(t, events[1].Err, errorfs.ErrInjected)
+	mu.Unlock()
+}
